Why This Is Asked
- Tests dynamic graph state and a non-trivial at-query metric.

Key Concepts
- Dynamic adjacency via hash sets, on-demand intersection, edge-id tracking, amortized performance.

Code Example
```javascript
class DynamicGraph {
  constructor(){ this.adj = new Map(); this.edges = new Map(); }
  addEdge(u,v,id){ if(!this.adj.has(u)) this.adj.set(u,new Set()); if(!this.adj.has(v)) this.adj.set(v,new Set()); this.adj.get(u).add(v); this.adj.get(v).add(u); this.edges.set(id,[u,v]); }
  removeEdge(id){ const e = this.edges.get(id); if(!e) return; const [u,v] = e; this.adj.get(u).delete(v); this.adj.get(v).delete(u); this.edges.delete(id); }
  twoStepPaths(u,v){ if(u===v) return 0; const A = this.adj.get(u) || new Set(); const B = this.adj.get(v) || new Set(); if(A.size < B.size){ let c=0; for(const x of A) if(B.has(x)) c++; return c; } else { let c=0; for(const x of B) if(A.has(x)) c++; return c; } }
}
```

Follow-up Questions
- How would you extend to directed graphs or multi-edges? Impact on correctness and complexity?
- What if you need to maintain this metric for many (u, v) pairs offline at once—any batching strategies?

## Why This Is Asked
Evaluates knowledge of practical data-structure trade-offs for dynamic ranking. Candidates should justify when to sort on demand vs. maintain auxiliary structures.

## Key Concepts
- Hash map for O(1) key access
- On-demand sorting for top-k retrieval
- Trade-off: simpler updates vs. slower top-k retrieval

## Code Example
```javascript
class CounterTopK {
  constructor() {
    this.counts = new Map(); // key -> count
  }
  add(key, delta) {
    const cur = this.counts.get(key) || 0;
    const next = cur + delta;
    if (next <= 0) this.counts.delete(key); else this.counts.set(key, next);
  }
  get(key) { return this.counts.get(key) || 0; }
  topK(k) {
    const arr = Array.from(this.counts.entries());
    arr.sort((a,b)=> b[1]-a[1] || a[0].localeCompare(b[0]));
    return arr.slice(0,k).map(([key]) => key);
  }
}
```

## Why This Is Asked
This question tests knowledge of 1D interval stabbing with dynamic updates and top-k queries across overlapping intervals—a common pattern in calendars, ad slot management, and reservation systems.

## Key Concepts
- **Segment tree**: Enables O(log N) node updates for interval operations and point queries
- **Per-node weight multisets**: Maintain counts of overlapping weights using BST/treap for O(log N) rank queries
- **Path aggregation**: Combines structures along the root-to-leaf path to answer sum and kth-largest queries

## Data Layout
1. **Coordinate compression**: Map all interval endpoints to sorted indices (0 to N-1)
2. **Segment tree nodes**: Each node stores a BST of (weight, count) pairs and nodeSum (total weight in that segment)
3. **Query paths**: Both sumWeightsAt and kthLargestWeightAt traverse O(log N) nodes along the path to point x

## Code Example
```javascript
class IntervalSet {
  constructor(points) {
    this.coords = this.compress(points);
    this.tree = this.build(0, this.coords.length - 1);
  }

  compress(points) {
    return [...new Set(points)].sort((a, b) => a - b);
  }

  insertInterval(L, R, w) {
    const l = this.lowerBound(L), r = this.lowerBound(R);
    this.update(this.tree.root, l, r, w, 1);
  }

  eraseInterval(L, R, w) {
    const l = this.lowerBound(L), r = this.lowerBound(R);
    this.update(this.tree.root, l, r, w, -1);
  }

  update(node, L, R, w, delta) {
    if (!node || L > node.r || R < node.l) return;
    if (L <= node.l && node.r <= R) {
      node.bst.insert(w, delta);
      node.sum += w * delta;
      return;
    }
    this.update(node.left, L, R, w, delta);
    this.update(node.right, L, R, w, delta);
  }

  sumWeightsAt(x) {
    const idx = this.lowerBound(x);
    return this.querySum(this.tree.root, idx);
  }

  querySum(node, idx) {
    if (!node) return 0;
    let res = node.sum;
    const mid = Math.floor((node.l + node.r) / 2);
    if (idx <= mid) res += this.querySum(node.left, idx);
    else res += this.querySum(node.right, idx);
    return res;
  }

  kthLargestWeightAt(x, k) {
    const idx = this.lowerBound(x);
    return this.queryKth(this.tree.root, idx, k);
  }

  queryKth(node, idx, k) {
    if (!node) return null;
    const counts = this.getPathCounts(node, idx);
    let lo = 0, hi = this.maxWeight;
    while (lo < hi) {
      const mid = Math.ceil((lo + hi) / 2);
      if (this.countGTE(counts, mid) >= k) lo = mid;
      else hi = mid - 1;
    }
    return lo;
  }
}
```

## Complexity Analysis
- **insertInterval/eraseInterval**: O(log N) nodes × O(log M) BST ops = O(log² N)
- **sumWeightsAt**: O(log N) path traversal
- **kthLargestWeightAt**: O(log N) × O(log maxWeight) = O(log² N)

## Why This Question Is Asked
This question tests understanding of stack augmentation, a practical pattern for maintaining auxiliary state. It demonstrates the ability to design data structures that support efficient queries while handling edge cases like duplicates and empty states.

## Key Concepts
- Two auxiliary stacks (minStack and maxStack) track running minima and maxima in sync with the main stack
- Each push/pop operation updates all three stacks atomically, preserving O(1) time complexity
- Duplicates are handled naturally since the min/max is recalculated at each step
- Empty stack edge cases must be handled (typically by checking stack length before accessing top)

## Code Example
```javascript
class MinMaxStack {
  constructor() {
    this.stack = [];
    this.minStack = [];
    this.maxStack = [];
  }

  push(x) {
    this.stack.push(x);
    this.minStack.push(
      this.minStack.length ? Math.min(x, this.minStack[this.minStack.length - 1]) : x
    );
    this.maxStack.push(
      this.maxStack.length ? Math.max(x, this.maxStack[this.maxStack.length - 1]) : x
    );
  }

  pop() {
    if (this.stack.length === 0) return undefined;
    this.minStack.pop();
    this.maxStack.pop();
    return this.stack.pop();
  }

  top() {
    return this.stack[this.stack.length - 1];
  }

  getMin() {
    return this.minStack[this.minStack.length - 1];
  }

  getMax() {
    return this.maxStack[this.maxStack.length - 1];
  }
}
```

## Why This Is Asked
Tests combining hash maps with a priority queue, handling duplicates, and lazy cleanup to keep top queries fast. Realistic usage: track most frequent items in a live feed.

## Key Concepts
- Hash map for per-item counts
- Max-heap (priority queue) for top element
- Lazy deletion to avoid costly updates
- Amortized analysis across interleaved ops

## Code Example
```javascript
class MaxHeap {
  constructor(){ this.a=[]; }
  size(){ return this.a.length; }
  push(x){ this.a.push(x); this.bubbleUp(this.a.length-1); }
  peek(){ return this.a[0]; }
  pop(){ if(!this.a.length) return null; const top=this.a[0]; const end=this.a.pop(); if(this.a.length){ this.a[0]=end; this.bubbleDown(0); } return top; }
  bubbleUp(i){ while(i>0){ const p=(i-1)>>1; if(this.a[p].count>=this.a[i].count) break; [this.a[p], this.a[i]]=[this.a[i], this.a[p]]; i=p; } }
  bubbleDown(i){ const n=this.a.length; while(true){ let l=i*2+1, r=l+1, largest=i; if(l<n && this.a[l].count>this.a[largest].count) largest=l; if(r<n && this.a[r].count>this.a[largest].count) largest=r; if(largest===i) break; [this.a[i], this.a[largest]]=[this.a[largest], this.a[i]]; i=largest; } }
}
class FrequencyDS {
  constructor(){ this.counts=new Map(); this.heap=new MaxHeap(); }
  insert(s){ const c=(this.counts.get(s)||0)+1; this.counts.set(s,c); this.heap.push({count:c, s}); }
  erase(s, cnt=1){ const old=this.counts.get(s)||0; const nc=Math.max(0, old-cnt); if(nc>0) this.counts.set(s,nc); else this.counts.delete(s); if(nc>0) this.heap.push({count:nc, s}); }
  countOf(s){ return this.counts.get(s)||0; }
  getMostFrequent(){ while(this.heap.size()){ const top=this.heap.peek(); const cur=this.counts.get(top.s)||0; if(cur!==top.count){ this.heap.pop(); continue; } return top.s; } return null; }
}
```

